SELECT SUBSTR('Oracle SQL', 1, 6) AS a,
       SUBSTR('Oracle SQL', -3)   AS b
  FROM dual;

SELECT cust_name, email
  FROM customers
 WHERE REGEXP_LIKE(email, '\.uz$');

SELECT first_name, hire_date
  FROM employees
 WHERE hire_date >= DATE '2022-01-01';

SELECT TO_CHAR(hire_date, 'DD.MM.YYYY')   AS d,
       TO_CHAR(hire_date, 'FMMonth YYYY') AS m
  FROM employees;

SELECT TO_NUMBER('42') AS a,
       TO_NUMBER('abc' DEFAULT 0 ON CONVERSION ERROR) AS b
  FROM dual;

SELECT * FROM products
 WHERE (category = 'Hardware' AND price > 1000)
    OR in_stock = 0;

SELECT first_name, commission_pct
  FROM employees
 ORDER BY commission_pct DESC NULLS LAST;

SELECT *
  FROM (SELECT first_name, salary FROM employees ORDER BY salary DESC)
 WHERE ROWNUM <= 3;

SELECT dept_id, LISTAGG(first_name, ', ') WITHIN GROUP (ORDER BY first_name) AS names
  FROM employees
 GROUP BY dept_id;

SELECT order_id, order_date,
       order_date - LAG(order_date) OVER (ORDER BY order_date) AS days_since_prev
  FROM orders;

SELECT e.first_name, d.dept_name
  FROM employees e
  JOIN departments d ON d.dept_id = e.dept_id;

SELECT e.first_name AS emp, m.first_name AS manager
  FROM employees e
  LEFT JOIN employees m ON m.emp_id = e.manager_id;

SELECT d.dept_name, e.first_name
  FROM departments d, employees e
 WHERE e.dept_id(+) = d.dept_id;

SELECT c.cust_name
  FROM customers c
 WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.cust_id = c.cust_id);

SELECT first_name, salary,
       salary - (SELECT ROUND(AVG(salary)) FROM employees) AS diff_from_avg
  FROM employees;

WITH dept_avg AS (
  SELECT dept_id, AVG(salary) AS avg_sal FROM employees GROUP BY dept_id
)
SELECT e.first_name, e.salary, ROUND(a.avg_sal) AS avg_sal
  FROM employees e JOIN dept_avg a ON a.dept_id = e.dept_id
 WHERE e.salary > a.avg_sal;

DECLARE
  v_cnt NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_cnt FROM employees;
  DBMS_OUTPUT.PUT_LINE('Сотрудников: ' || v_cnt);
END;

DECLARE
  r employees%ROWTYPE;
BEGIN
  SELECT * INTO r FROM employees WHERE emp_id = 100;
  DBMS_OUTPUT.PUT_LINE(r.first_name || ' ' || r.salary);
END;

