DECLARE
  CURSOR c(p_dept NUMBER) IS SELECT first_name FROM employees WHERE dept_id = p_dept;
  v_name employees.first_name%TYPE;
BEGIN
  OPEN c(10);
  LOOP
    FETCH c INTO v_name;
    EXIT WHEN c%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(c%ROWCOUNT || '. ' || v_name);
  END LOOP;
  CLOSE c;
END;

DECLARE
  v NUMBER;
BEGIN
  SELECT salary INTO v FROM employees WHERE emp_id = -1;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('Нет такого сотрудника');
END;

DECLARE
  TYPE t_names IS TABLE OF employees.first_name%TYPE;
  v t_names;
BEGIN
  SELECT first_name BULK COLLECT INTO v FROM employees;
  DBMS_OUTPUT.PUT_LINE('Загружено: ' || v.COUNT);
END;

DECLARE
  v_cnt NUMBER;
  v_tab VARCHAR2(30) := 'EMPLOYEES';
BEGIN
  EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || DBMS_ASSERT.SQL_OBJECT_NAME(v_tab) INTO v_cnt;
  DBMS_OUTPUT.PUT_LINE(v_cnt);
END;

